<?php
require_once __DIR__.'/../app/bootstrap.php'; require_admin(); ensure_news_schema();
$adminPage='news';$adminTitle='Noticias del sitio';$adminSubtitle='Publica novedades con BBCode, HTML seguro, enlaces y videos incrustados';
$id=(int)($_GET['edit']??0);$editing=null;
if($id){$q=db()->prepare('SELECT * FROM news WHERE id=?');$q->execute([$id]);$editing=$q->fetch()?:null;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'save';
 if($action==='delete'){$nid=(int)$_POST['id'];db()->prepare('DELETE FROM news WHERE id=?')->execute([$nid]);flash('success','Noticia eliminada.');redirect('../admin/news.php');}
 if($action==='toggle_enabled'){$value=isset($_POST['news_enabled'])?'1':'0';db()->prepare('INSERT INTO settings(`key`,value) VALUES("news_enabled",?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute([$value]);flash('success',$value==='1'?'Sección de noticias habilitada en el inicio.':'Sección de noticias ocultada del inicio.');redirect('../admin/news.php');}
 $nid=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$content=trim($_POST['content']??'');
 if(mb_strlen($title)<5||mb_strlen($content)<10)throw new RuntimeException('El título y el contenido son demasiado cortos.');
 $format=in_array($_POST['content_format']??'mixed',['bbcode','html','mixed'],true)?$_POST['content_format']:'mixed';
 $status=in_array($_POST['status']??'draft',['draft','published','hidden'],true)?$_POST['status']:'draft';
 $cover=upload_image('cover_image','news');$slug=unique_news_slug($title,$nid);$published=$status==='published'?date('Y-m-d H:i:s'):null;
 if($nid){
   $old=db()->prepare('SELECT cover_image,published_at FROM news WHERE id=?');$old->execute([$nid]);$row=$old->fetch();if(!$row)throw new RuntimeException('Noticia inexistente.');
   $cover=$cover?:$row['cover_image'];$published=$status==='published'?($row['published_at']?:date('Y-m-d H:i:s')):null;
   db()->prepare('UPDATE news SET title=?,slug=?,excerpt=?,content=?,content_format=?,cover_image=?,status=?,featured=?,show_home=?,published_at=?,updated_at=NOW() WHERE id=?')->execute([$title,$slug,trim($_POST['excerpt']??''),$content,$format,$cover,$status,isset($_POST['featured'])?1:0,isset($_POST['show_home'])?1:0,$published,$nid]);
   flash('success','Noticia actualizada correctamente.');
 }else{
   db()->prepare('INSERT INTO news(created_by,title,slug,excerpt,content,content_format,cover_image,status,featured,show_home,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([(int)user()['id'],$title,$slug,trim($_POST['excerpt']??''),$content,$format,$cover,$status,isset($_POST['featured'])?1:0,isset($_POST['show_home'])?1:0,$published]);
   flash('success','Noticia creada correctamente.');
 }
 redirect('../admin/news.php');
}
$news=db()->query('SELECT n.*,u.username,p.display_name FROM news n JOIN users u ON u.id=n.created_by LEFT JOIN profiles p ON p.user_id=u.id ORDER BY n.featured DESC,n.created_at DESC')->fetchAll();
require __DIR__.'/partials/header.php';
