<section class="panel-card"><div class="panel-head"><div><h2>Noticias creadas</h2><p><?=count($news)?> contenidos registrados</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Noticia</th><th>Estado</th><th>Inicio</th><th>Fecha</th><th>Acciones</th></tr></thead><tbody><?php foreach($news as $n):?><tr><td><b><?=e($n['title'])?></b><small><?=e($n['display_name']?:$n['username'])?> · <?=$n['views']?> visitas <?=$n['featured']?'· ⭐ Destacada':''?></small></td><td><span class="status <?=e($n['status'])?>"><?=e($n['status'])?></span></td><td><?=$n['show_home']?'✅':'—'?></td><td><?=date('d/m/Y H:i',strtotime($n['created_at']))?></td><td><div class="table-actions"><a class="admin-btn small secondary" href="?edit=<?=$n['id']?>">Editar</a><?php if($n['status']==='published'):?><a class="admin-btn small" target="_blank" href="<?=url('news.php?id='.$n['id'])?>">Ver</a><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><button class="admin-btn small danger" name="id" value="<?=$n['id']?>" data-confirm="¿Eliminar definitivamente esta noticia?">Eliminar</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
